    conversationScope: "root",
    durationMs: 2000,
    status: "succeeded",
    content: "PRIVATE",
    verdict: null,
    usage: { inputTokens: 10, outputTokens: 5, cachedTokens: 0, requestCount: 1, totalNanoAiu: 0 },
  },
});

function promiseGate() {
  let resolve!: () => void;
  const promise = new Promise<void>((done) => {
    resolve = done;
  });
  return { promise, resolve };
}

const setup = Effect.fnUntraced(function* (
  fake: Fake,
  initialNativeThreadId?: string,
  initialSelection: ModelSelection = selection,
  runtimeSessionId = sessionId,
) {
  const adapter = yield* makeAdapter(
    { instanceId, settings, environment: { HOME: "/test-account" } },
    { clientFactory: () => fake.client },
  );
  const runtime = yield* adapter.openSession({
    threadId,
    providerSessionId: runtimeSessionId,
    modelSelection: initialSelection,
    runtimePolicy: policy,
    ...(initialNativeThreadId ? { initialNativeThreadId } : {}),
  });
  const emitted: ProviderAdapter.ProviderAdapterV2Event[] = [];
  const eventQueue = yield* Queue.unbounded<ProviderAdapter.ProviderAdapterV2Event>();
  const eventFiber = yield* runtime.events.pipe(
    Stream.runForEach((event) =>
      Effect.sync(() => {
        emitted.push(event);
      }).pipe(Effect.andThen(Queue.offer(eventQueue, event))),
    ),
    Effect.forkScoped,
  );
  const takeEvent = Effect.fnUntraced(function* (
    predicate: (event: ProviderAdapter.ProviderAdapterV2Event) => boolean,
  ) {
    while (true) {
      const event = yield* Queue.take(eventQueue);
      if (predicate(event)) return event;
    }
  });
  const thread = yield* runtime.ensureThread({
    threadId,
    modelSelection: initialSelection,
    runtimePolicy: policy,
  });
  const start = Effect.fnUntraced(function* (ordinal = 1, turnSelection = initialSelection) {
    const now = yield* DateTime.now;
    const appThread: OrchestrationV2AppThread = {
      id: threadId,
      projectId: ProjectId.make("project"),
      title: "Test",
      providerInstanceId: instanceId,
      modelSelection: turnSelection,
      runtimeMode: policy.runtimeMode,
      interactionMode: "default",
      branch: null,
      worktreePath: null,
      activeProviderThreadId: thread.id,
      lineage: { parentThreadId: null, relationshipToParent: null, rootThreadId: threadId },
      forkedFrom: null,
      createdBy: "user",
      creationSource: "web",
      createdAt: now,
      updatedAt: now,
      archivedAt: null,
      settledOverride: null,
      settledAt: null,
      lastVisitedAt: null,
      deletedAt: null,
    };
    yield* runtime.startTurn({
      appThread,
      threadId,
      runId: RunId.make(`run-${ordinal}`),
      runOrdinal: ordinal,
      providerTurnOrdinal: ordinal,
      attemptId: RunAttemptId.make(`attempt-${ordinal}`),
      rootNodeId: NodeId.make(`root-${ordinal}`),
      providerThread: thread,
      message: {
        messageId: MessageId.make(`user-${ordinal}`),
        text: "Hello",
        attachments: [],
        createdBy: "user",
        creationSource: "web",
      },
      modelSelection: turnSelection,
      runtimePolicy: policy,
    });
  });
  const drain = () => runtime.readThreadSnapshot({ providerThread: thread });
  return { runtime, thread, emitted, start, drain, takeEvent, eventFiber };
});

const provide = <A, E, R>(effect: Effect.Effect<A, E, R>) =>
  effect.pipe(
    Effect.provideService(ProviderHost.ProviderHost, host),
    Effect.provide(McpProviderSessions.layer),
    Effect.scoped,
  );

describe("native Copilot V2", () => {
  it.effect(
    "preserves skill ownership, fresh inventory and errors across live session scopes",
    () =>
      provide(
        Effect.gen(function* () {
          const first = fakeSdk();
          const second = fakeSdk();
          for (const fake of [first, second])
            fake.setSkills({
              skills: [
                {
                  name: "review",
                  description: "Review changes",
                  source: "project",
                  userInvocable: true,
                  enabled: true,
                  path: "/workspace/.agents/skills/review/SKILL.md",
                },
              ],
            });
          let nextClient = 0;
          const inventories = new Map<string, ReadonlyArray<ServerProviderSkill>>();
          const adapter = yield* makeAdapter(
            { instanceId, settings, environment: { HOME: "/test-account" } },
            {
              clientFactory: () => (nextClient++ === 0 ? first.client : second.client),
              onSkills: (cwd, discovered) => {
                if (discovered) inventories.set(cwd, discovered);
                else inventories.delete(cwd);
              },
            },
          );
          if (!adapter.setSkillEnabled)
            throw new Error("Copilot instance skill controls are missing");
          const setSkillEnabled = adapter.setSkillEnabled;
          const unavailable = yield* adapter
            .setSkillEnabled({ skillName: "review", enabled: false })
            .pipe(Effect.result);
          assert.equal(unavailable._tag, "Failure");
          if (unavailable._tag === "Failure")
            assert.equal(unavailable.failure.reason, "session_unavailable");

          const firstScope = yield* Effect.acquireRelease(Scope.make(), (scope) =>
            Scope.close(scope, Exit.succeed(undefined)),
          );
          const open = Effect.fnUntraced(function* (id: string, scope: Scope.Scope, cwd: string) {
            const ownThread = ThreadId.make(id);
            const runtime = yield* adapter
              .openSession({
                threadId: ownThread,
                providerSessionId: ProviderSessionId.make(id),
                modelSelection: selection,
                runtimePolicy: { ...policy, cwd },
              })
              .pipe(Effect.provideService(Scope.Scope, scope));
            yield* runtime.ensureThread({
              threadId: ownThread,
              modelSelection: selection,
              runtimePolicy: { ...policy, cwd },
            });
          });
          yield* open("first-runtime", firstScope, "/workspace/first");
          yield* adapter.setSkillEnabled({ skillName: "review", enabled: false });
          assert.isFalse(first.skills[0]?.enabled);
          assert.deepEqual(inventories.get("/workspace/first"), []);
          yield* adapter.setSkillEnabled({ skillName: "review", enabled: true });
          assert.equal(inventories.get("/workspace/first")?.[0]?.name, "review");
          const readStarted = Promise.withResolvers<void>();
          const releaseRead = Promise.withResolvers<void>();
          first.setSkillsRead(async () => {
            const response = { skills: first.skills.map((skill) => ({ ...skill })) };
            readStarted.resolve();
            await releaseRead.promise;
            return response;
          });
          yield* Effect.gen(function* () {
            const disabling = yield* setSkillEnabled({ skillName: "review", enabled: false }).pipe(
              Effect.forkScoped,
            );
            yield* Effect.promise(() => readStarted.promise);
            const enabling = yield* setSkillEnabled({
              skillName: "review",
              enabled: true,
            }).pipe(Effect.forkScoped({ startImmediately: true }));
            assert.isFalse(first.skills[0]?.enabled);
            releaseRead.resolve();
            yield* Fiber.join(disabling);
            yield* Fiber.join(enabling);
            assert.isTrue(first.skills[0]?.enabled);
            assert.equal(inventories.get("/workspace/first")?.[0]?.name, "review");
          }).pipe(Effect.ensuring(Effect.sync(() => releaseRead.resolve())));
          first.setSkillsRead(undefined);

          const secondScope = yield* Effect.acquireRelease(Scope.make(), (scope) =>
            Scope.close(scope, Exit.succeed(undefined)),
          );
          yield* open("second-runtime", secondScope, "/workspace/second");
          const ambiguous = yield* adapter
            .setSkillEnabled({ skillName: "review", enabled: false })
            .pipe(Effect.result);
          assert.equal(ambiguous._tag, "Failure");
          if (ambiguous._tag === "Failure")
            assert.equal(ambiguous.failure.reason, "session_required");
          assert.isTrue(first.skills[0]?.enabled);
          assert.isTrue(second.skills[0]?.enabled);

          yield* adapter.setSkillEnabled({
            skillName: "review",
            enabled: false,
            providerSessionId: ProviderSessionId.make("second-runtime"),
          });
          assert.isTrue(first.skills[0]?.enabled);
          assert.isFalse(second.skills[0]?.enabled);
          assert.deepEqual(inventories.get("/workspace/second"), []);

          first.setSkillFailure(new Error("Native skill update rejected"));
          const failed = yield* adapter
            .setSkillEnabled({
              skillName: "review",
              enabled: false,
              providerSessionId: ProviderSessionId.make("first-runtime"),
            })
            .pipe(Effect.result);
          assert.equal(failed._tag, "Failure");
          if (failed._tag === "Failure") {
            assert.equal(failed.failure.reason, "operation_failed");
            assert.isDefined(failed.failure.cause);
          }
          assert.isTrue(first.skills[0]?.enabled);
          assert.equal(inventories.get("/workspace/first")?.[0]?.name, "review");
          yield* Scope.close(firstScope, Exit.succeed(undefined));
          yield* adapter.setSkillEnabled({ skillName: "review", enabled: true });
          assert.isTrue(second.skills[0]?.enabled);
          yield* Scope.close(secondScope, Exit.succeed(undefined));
          const closed = yield* adapter
            .setSkillEnabled({ skillName: "review", enabled: false })
            .pipe(Effect.result);
          assert.equal(closed._tag, "Failure");
          if (closed._tag === "Failure") assert.equal(closed.failure.reason, "session_unavailable");
        }),
      ),
  );

  it.effect.each([undefined, "native-copilot"])(
    "starts and settles with unsupported extensions disabled, native resume %s",
    (nativeId) =>
      provide(
        Effect.gen(function* () {
          const fake = fakeSdk({ persistedExtensions: true });
