                  (event.type === "node.updated" && event.node.runtimeRequestId === request.id) ||
                  (event.type === "turn_item.updated" &&
                    (event.turnItem.type === "approval_request" ||
                      event.turnItem.type === "user_input_request") &&
                    event.turnItem.requestId === request.id),
